c32 = "# GEO\u6807\u51c6\u4f53\u7cfb\u4e0e\u884c\u4e1a\u6307\u6570\n\n> \u8c01\u5b9a\u4e49\u884c\u4e1a\u8bed\u8a00\uff0c\u8c01\u5b9a\u4e49\u884c\u4e1a\u89c4\u5219\uff0c\u8c01\u62e5\u6709\u884c\u4e1a\u8bdd\u8bed\u6743\u3002\n\n---\n\n## \u4e00\u3001\u6807\u51c6\u4f53\u7cfb\u6982\u89c8\n\n| \u6807\u51c6 | \u5df2\u5b58\u5728\u7684\u6587\u6863\u57fa\u7840 | \u672c\u6587\u6863\u7684\u5ef6\u4f38 |\n|--------|-------------------|----------------|\n| GEO\u5b9e\u4f53\u6807\u51c6 | 25_\u672c\u4f53\u6a21\u578b | GEO Entity ID\u7cfb\u7edf |\n| GEO\u80fd\u529b\u6807\u51c6 | 13_\u804c\u4e1a\u751f\u6001 | \u80fd\u529b\u5206\u7c7b\u6811 |\n| GEO\u884c\u4e1a\u5206\u7c7b\u6807\u51c6 | 02_\u9886\u57df\u6a21\u578b | AI-Native\u884c\u4e1a\u5206\u7c7b |\n| GEO\u53ef\u89c1\u5ea6\u6807\u51c6 | 16_GEO\u8bc4\u5206\u7b97\u6cd5 | \u53ef\u89c1\u5ea6\u6307\u6570 |\n| GEO\u4fe1\u4efb\u6807\u51c6 | 23_\u5408\u89c4\u4e0e\u98ce\u9669 | \u4fe1\u4efb\u7b49\u7ea7\u4f53\u7cfb |\n| GEO\u8d21\u732e\u6807\u51c6 | 31_GEO\u8d21\u732e\u8005\u751f\u6001 | \u8d21\u732e\u6307\u6570 |\n| GEO\u63a8\u8350\u6807\u51c6 | 22_GEO\u6d4b\u91cf\u65b9\u6cd5\u8bba | \u63a8\u8350\u900f\u660e\u5ea6\u6807\u51c6 |\n\n## \u4e8c\u3001GEO Entity ID\n\n\u7edf\u4e00\u5b9e\u4f53\u8eab\u4efd\u6807\u8bc6\uff1a\n- \u4f01\u4e1a\uff1aGEO-COMPANY-{id}\n- \u4e2a\u4eba\uff1aGEO-PERSON-{id}\n- \u4ea7\u54c1\uff1aGEO-PRODUCT-{id}\n- \u80fd\u529b\uff1aGEO-CAPABILITY-{id}\n\n## \u4e09\u3001\u884c\u4e1a\u6307\u6570\n\n| \u6307\u6570 | \u5185\u5bb9 | \u53c2\u8003 |\n|---------|------|--------|\n| GEO Enterprise 500 | \u7efc\u5408GEO\u8bc4\u5206\u6392\u540d\u524d500\u7684\u4f01\u4e1a | S&P 500 |\n| GEO City Index | \u57ce\u5e02GEO\u4ea7\u4e1a\u53d1\u5c55\u6307\u6570 | \u62db\u5546\u5f15\u8d44\u70ed\u56fe |\n| GEO Talent Index | \u4eba\u624dGEO\u6280\u80fd\u4e0e\u8d21\u732e\u6392\u540d | \u804c\u4e1a\u6392\u540d |\n| GEO Opportunity Index | \u884c\u4e1a\u673a\u4f1a\u4e0e\u589e\u957f\u6307\u6570 | \u5546\u673a\u53d1\u73b0 |\n\n## \u56db\u3001\u6807\u51c6\u7f51\u7edc\u6548\u5e94\n\n\u6807\u51c6 \u2192 \u66f4\u591a\u4f01\u4e1a\u9002\u914d \u2192 \u66f4\u591a\u6570\u636e \u2192 AI\u7406\u89e3\u66f4\u51c6\u786e \u2192 \u66f4\u591a\u7528\u6237\u4f7f\u7528 \u2192 \u6807\u51c6\u66f4\u5f3a\n"
